const r = $('Mail und Signatur laden').item.json;
const c = $input.item.json.content;
const body = (Array.isArray(c) ? c : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join('\n\n').trim();
if (!body) throw new Error('Kein Entwurfstext erzeugt');
const neu = r.art === 'neu';
// Produktname aus der Einstellung produkt_name für Fehlertexte; ohne Namen neutral (Stefan 18.10.2026)
const P = String(r.produkt_name || '').trim();

// Name in der Signatur: Platzhalter {Name} der Postfach-Signatur wird durch den Namen der anfragenden Person ersetzt
const name = String(r.signatur_name || '').trim();
const platzhalter = /\{Name\}/;
if (!name && (platzhalter.test(String(r.signatur_html || '')) || platzhalter.test(String(r.signatur_text || '')))) throw new Error('Für die Signatur ist kein Name hinterlegt (' + (P ? P + '-Oberfläche' : 'Oberfläche') + ', Meine Einstellungen). Entwurf wurde nicht angelegt.');
const sigText = String(r.signatur_text || '').trim().replace(/\{Name\}/g, name);
// Keine festen Farben: weder im Text noch in der Signatur. Farb- und Hintergrundangaben der Signatur werden entfernt,
// damit das Mailprogramm seine Standardfarben nutzt ("keine Farbe").
// Schriftart und -größe kommen vom Postfach (Ally-Oberfläche) und gelten für Mailtext und Signatur.
const SCHRIFT = String(r.schrift_stapel || 'Helvetica Neue, Helvetica, Arial, sans-serif').replace(/["'<>;]/g, '');
const GROESSE = Number(r.schrift_groesse) >= 10 && Number(r.schrift_groesse) <= 20 ? Number(r.schrift_groesse) : 13;
const schriftStil = 'font-family: ' + SCHRIFT + '; font-size: ' + GROESSE + 'px;';
const ohneFarbe = h => String(h || '')
  .replace(/\sstyle\s*=\s*(["'])([\s\S]*?)\1/gi, (m, q, s) => {
    const rest = s.split(';').map(x => x.trim()).filter(x => x && !/^(color|background|background-color)\s*:/i.test(x)).map(x => /^font-size\s*:/i.test(x) ? 'font-size: ' + GROESSE + 'px' : (/^font-family\s*:/i.test(x) ? 'font-family: ' + SCHRIFT : x)).join('; ');
    return rest ? ' style=' + q + rest + ';' + q : '';
  })
  .replace(/\s(color|bgcolor|text|link|vlink|alink|face|size)\s*=\s*(["'])[^"']*\2/gi, '');
const esc = s => String(s ?? '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const sigHtml = ohneFarbe(String(r.signatur_html || '').trim()).replace(/\{Name\}/g, esc(name));
const pStyle = 'margin:0 0 12pt 0; ' + schriftStil;
const htmlBody = body.split(/\n{2,}/).map(p => '<p style="' + pStyle + '">' + esc(p).split('\n').join('<br>') + '</p>').join('');
// KI-Hinweis unter der Signatur, wenn für alle eingeschaltet (Seite Mail-Entwürfe, Für alle; Stefan 17.10.2026)
const KI = r.ki_hinweis === true ? 'Erstellt mit KI-Unterstützung.' : '';
const fullText = body + (sigText ? '\n\n' + sigText : '') + (KI ? '\n\n' + KI : '');
const fullHtml = '<html><head><meta charset="utf-8"></head><body><div style="direction: ltr; ' + schriftStil + '">' + htmlBody + '</div>' + (sigHtml ? '<div style="' + schriftStil + '">' + sigHtml + '</div>' : '') +
  (KI ? '<div style="' + schriftStil + '"><p style="margin:12pt 0 0 0; ' + schriftStil + '">' + KI + '</p></div>' : '') + '</body></html>';
if (/\{Name\}/.test(sigHtml + sigText)) throw new Error('Signatur enthält noch den Platzhalter {Name}. Entwurf wurde nicht angelegt.');
if (/style\s*=\s*(["'])[^"']*(color|background)\s*:/i.test(sigHtml) || /\s(color|bgcolor)\s*=/i.test(sigHtml)) throw new Error('Entwurf enthält noch eine feste Farbe. Entwurf wurde nicht angelegt.');

const ascii = s => /^[\x20-\x7e]*$/.test(s);
const word = s => ascii(s) ? s : '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=';
const addr = (name, mail) => name ? (ascii(name) ? '"' + name.replace(/"/g, '') + '"' : word(name)) + ' <' + mail + '>' : mail;
const b64 = s => Buffer.from(s, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n');
const winkel = id => { const t = String(id || '').trim(); return !t ? '' : (t.startsWith('<') ? t : '<' + t + '>'); };

const betreff = String(r.betreff || '').trim();
const subject = neu ? betreff : (/^(re|aw|antw)\s*:/i.test(betreff) ? betreff : 'Re: ' + betreff);
const an = String(r.antwort_an || r.absender || '').trim();
const inReplyTo = neu ? '' : winkel(r.message_id);
const refs = neu ? '' : [String(r.referenzen || '').trim(), inReplyTo].filter(Boolean).join(' ');
const boundary = 'ally-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const msgId = '<ally-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '@' + (String(r.postfach || '').split('@')[1] || 'ally.invalid') + '>';

const lines = [
  'From: ' + addr(r.absender_name_einstellung || '', r.postfach),
  an ? 'To: ' + addr(r.absender_name || '', an) : null,
  'Subject: ' + word(subject),
  'Date: ' + new Date().toUTCString().replace('GMT', '+0000'),
  'Message-ID: ' + msgId,
  inReplyTo ? 'In-Reply-To: ' + inReplyTo : null,
  refs ? 'References: ' + refs : null,
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + boundary + '"',
  '',
  '--' + boundary,
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  b64(fullText),
  '--' + boundary,
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  b64(fullHtml),
  '--' + boundary + '--',
  ''
].filter(l => l !== null);

return { json: { rueckfrage_id: r.id, art: neu ? 'neue Mail' : 'Antwort', postfach: r.postfach, ordner: r.entwurf_ordner || 'Entwürfe', empfaenger: an || 'noch offen (bitte selbst eintragen)', betreff: subject, entwurf_text: body, rfc822: lines.join('\r\n') } };

// Kein Entwurf ohne gültige Mail: klarer Grund statt stillem Abbruch (Mail fehlt, Postfach pausiert/nicht angebunden, nicht zuständig, Adresse ungültig)
const j = $input.item.json;
if (j.id === null || j.id === undefined) throw new Error('Kein Entwurf angelegt: ' + (j.grund || 'Die Mail konnte nicht geladen werden.'));
return { json: j };

// Platzhalter in eckigen Klammern im HTML-Teil des Entwurfs rot (Vorgabe Stefan, 13.10.2026). Text-Teil und Signatur bleiben unverändert.
const ROT = '#D00000';
const j = $input.item.json;
const kopf = 'Content-Type: text/html; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n';
const teile = String(j.rfc822 || '').split(kopf);
if (teile.length !== 2) throw new Error('HTML-Teil des Entwurfs nicht gefunden. Entwurf wurde nicht angelegt.');
const ende = teile[1].indexOf('\r\n--');
if (ende < 0) throw new Error('HTML-Teil des Entwurfs unvollständig. Entwurf wurde nicht angelegt.');
const html = Buffer.from(teile[1].slice(0, ende).replace(/\r\n/g, ''), 'base64').toString('utf8');
// Nur der Mailtext (erster Block bis zum ersten </div>), nicht die Signatur
const grenze = html.indexOf('</div>');
if (grenze < 0) throw new Error('Aufbau des Entwurfs unbekannt. Entwurf wurde nicht angelegt.');
const neu = html.slice(0, grenze).replace(/\[([^\[\]\n<>]{1,150})\]/g, '<span style="color: ' + ROT + ';">[$1]</span>') + html.slice(grenze);
const b64 = Buffer.from(neu, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n');
return { json: { ...j, rfc822: teile[0] + kopf + b64 + teile[1].slice(ende) } };

