-- KI-Budget erreicht (ki_gesperrt): kein Entwurf. Eine dafuer angelegte neue Mail wird wie bei einem KI-Fehler als fehlgeschlagen markiert;
-- der Grund (ki_sperre_text) geht im Feld error an den Aufrufer (Ally bzw. Arbeitsbereiche), ohne Fehlerausfuehrung (Stefan 18.10.2026)
WITH upd AS (
  UPDATE mail_rueckfragen SET status = 'fehlgeschlagen', geaendert_am = now()
  WHERE id = $1::int AND art = 'neu' AND status = 'neu'
  RETURNING id
)
SELECT $2::text AS error;
